(()=>{
 const panel=document.createElement('details');panel.id='collision-obstacle-panel';panel.className='advanced';panel.innerHTML='<summary>3D collision obstacles</summary><p class="animation-intro">Enable Collide with a surface above. The selected layer’s obstacle appears as a blue wireframe when the grid is on. Particles bounce off its outside or disappear on contact.</p><label>Obstacle shape<select id="obstacle-shape" aria-label="Collision obstacle shape"><option value="plane">Horizontal floor</option><option value="sphere">Sphere</option><option value="box">Box</option></select></label><div id="obstacle-fields"></div><button id="try-obstacle" type="button">Add sphere deflection example</button><p class="animation-intro">Measurements are in effect-local centimeters. These mathematical shapes do not add visible meshes to your Unreal level. Very fast particles can pass through thin obstacles between simulation steps.</p>';
 const host=panel.querySelector('#obstacle-fields');for(const [key,[name,min,max,value]]of Object.entries(EmberCollisions.ranges)){const label=document.createElement('label'),input=document.createElement('input');label.textContent=name;label.dataset.obstacleField=key;input.id='obstacle-'+key;input.type='number';input.min=min;input.max=max;input.step='any';input.value=value;input.setAttribute('aria-label',name);input.oninput=()=>{if(!input.checkValidity()||!Number.isFinite(input.valueAsNumber))return;state[key]=input.valueAsNumber;persist();};label.append(input);host.append(label);}
 $('#dynamics-panel').after(panel);const select=$('#obstacle-shape');select.onchange=()=>{state.colliderType=select.value;sync();persist();};$('#try-obstacle').onclick=()=>addParticleLayer({...EmberCatalog.presets.find(p=>p.id==='custom'),name:'Sphere deflection',motion:'aimed',shape:'point',speed:100,life:6,spread:30,positionX:-150,positionZ:52,trail:true,trailLength:2,bounce:true,colliderType:'sphere',colliderZ:60,colliderRadius:50,color:'#54d8ff'},'Sphere deflection');
 function refresh(){const type=state.colliderType||'plane',disabled=!state.bounce||state.motion==='orbit';select.value=type;select.disabled=disabled;for(const key of Object.keys(EmberCollisions.ranges)){const input=$('#obstacle-'+key);input.value=state[key]??EmberCollisions.defaults[key];input.disabled=disabled;input.closest('label').hidden=type==='plane'||(key==='colliderRadius'&&type!=='sphere')||(key.startsWith('colliderSize')&&type!=='box');}$('#dynamics-collisionHeight').disabled=disabled||type!=='plane';}
 window.emberColliderPreviewSettings=()=>EmberAnimation.evaluate(state,layers[activeLayer]?.time||0);
 const previous=sync;sync=()=>{previous();refresh();};const oldBounce=$('#advanced-bounce').oninput;$('#advanced-bounce').oninput=event=>{oldBounce(event);refresh();};refresh();
})();
